SELECT CASE WHEN monthly_fee >= 207 THEN 'high' WHEN monthly_fee >= 56 THEN 'mid' ELSE 'low' END AS monthly_fee_bucket, SORT_ARRAY(COLLECT_SET(status)) AS status_list, MAX(monthly_fee) - MIN(monthly_fee) AS monthly_fee_range FROM subscriptions GROUP BY CASE WHEN monthly_fee >= 207 THEN 'high' WHEN monthly_fee >= 56 THEN 'mid' ELSE 'low' END ORDER BY monthly_fee_range DESC, monthly_fee_bucket LIMIT 50;
